#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
# Detect a PowerShell host usable from bash (pwsh preferred, powershell.exe fallback).
_pick_ps() {
  if command -v pwsh         >/dev/null 2>&1; then PS=pwsh
  elif command -v powershell.exe >/dev/null 2>&1; then PS=powershell.exe
  else return 1; fi
}

run_wizard() {

TOTAL_STAGES=4

banner "Dev Drive setup (VHD on C:)"
note "Creates a portable Dev Drive as a dynamic .vhdx on your NVMe C:"
note "drive, then moves your dev trees + caches into it via junctions -"
note "old paths keep working, so no tool needs reconfiguring, and every"
note "step is reversible. Defender automatically uses async performance"
note "mode on the Dev Drive (that's the whole speed benefit)."
note ""
note "Needs: one UAC prompt (Stage 2). Your C: must be NTFS Win11 -"
note "checked in Stage 1. Trees that are busy/locked are skipped and"
note "can be migrated by re-running this wizard later."

# ── Stage 1: inventory + plan ─────────────────────────────────────────────
stage "Inventory + plan"
if ! _pick_ps; then
  warn "no PowerShell host (pwsh / powershell.exe) on PATH - run this wizard from Git Bash on Windows."
  return 1
fi
say "PowerShell host: $PS"
say "Probing (read-only)…"

declare -A I=() TP=() TS=()
while IFS=$'\t' read -r k a b c; do
  case "$k" in
    TREE) TP["$a"]="$b"; TS["$a"]="$c" ;;
    *)    [[ -n "${k:-}" ]] && I["$k"]="$a" ;;
  esac
done < <("$PS" -NoProfile -Command '
"BUILD`t" + [System.Environment]::OSVersion.Version.Build
"DISKPART`t" + [bool](Get-Command diskpart -ErrorAction SilentlyContinue)
"VUSED`t" + [bool](Get-Volume -DriveLetter V -ErrorAction SilentlyContinue)
"CFREE`t" + [math]::Round((Get-Volume C).SizeRemaining/1GB,1)
foreach ($t in @(
  @("dev",   "C:\dev"),
  @("gradle",    (Join-Path $env:USERPROFILE ".gradle")),
  @("bun",       (Join-Path $env:USERPROFILE ".bun")),
  @("m2",        (Join-Path $env:USERPROFILE ".m2")),
  @("pnpm",      (Join-Path $env:LOCALAPPDATA "pnpm")),
  @("npmcache",  (Join-Path $env:LOCALAPPDATA "npm-cache"))
)) {
  if (Test-Path $t[1]) {
    $gb = [math]::Round((Get-ChildItem $t[1] -Recurse -File -ErrorAction SilentlyContinue |
      Measure-Object Length -Sum).Sum/1GB, 1)
    "TREE`t$($t[0])`t$($t[1])`t$gb"
  } else { "TREE`t$($t[0])`t$($t[1])`tabsent" }
}
' | tr -d '\r')

if [[ "${I[DISKPART]:-}" != "True" ]]; then
  warn "diskpart not found - cannot create the VHD."
  return 1
fi
if (( ${I[BUILD]:-0} < 22621 )); then
  warn "Windows build ${I[BUILD]} predates Dev Drive support (needs 22621+)."
  return 1
fi
if [[ "${I[VUSED]:-}" == "True" ]]; then
  warn "drive letter V: is already in use - free it or edit this wizard to pick another letter."
  return 1
fi
say "Windows build ${I[BUILD]} - Dev Drive capable."
say "C: free: ${I[CFREE]:-?} GB"
say ""
say "Candidates to migrate into the Dev Drive:"
ORDER=(dev gradle bun m2 pnpm npmcache)
USAGE=0
for t in "${ORDER[@]}"; do
  if [[ "${TS[$t]:-absent}" == "absent" ]]; then
    say "  $t: (absent, skipped)"
    continue
  fi
  say "  $t: ${TP[$t]}  (${TS[$t]} GB)"
  USAGE=$(awk -v a="$USAGE" -v b="${TS[$t]}" 'BEGIN{print a+b}')
done
say ""
say "Total to move: ~${USAGE} GB. The VHD is dynamic - it only consumes"
say "what you actually put in it, the max is a ceiling."
ask VHD_MAX "Max size GB for the Dev Drive [80]:"
VHD_MAX="${VHD_MAX:-80}"
NEED=$(awk -v u="$USAGE" 'BEGIN{printf "%d", u*1.5+10}')
if (( VHD_MAX < NEED )); then
  warn "max ${VHD_MAX} GB is tight for ~${USAGE} GB of data (want ceiling ≥ ${NEED} GB)."
  confirm "Continue anyway?"
fi
say ""
say "Close IDEs, Gradle daemons, dev servers etc. before continuing -"
say "anything with open handles is skipped (re-run this wizard later)."
ask SKIP "Trees to SKIP (comma list from: dev,gradle,bun,m2,pnpm,npmcache) [none]:"
SKIP="${SKIP// /}"
if ! confirm "Create the Dev Drive and migrate the listed trees?"; then
  warn "Cancelled - nothing was changed."
  return 0
fi

# ── Stage 2: create the Dev Drive (one UAC prompt) ────────────────────────
stage "Create Dev Drive (one UAC prompt)"
TMPD="${TMPDIR:-/tmp}"
LOG="$TMPD/devdrive-setup.log"
LAUNCHER="$TMPD/devdrive-launcher.ps1"
PSHOST="$(command -v "$PS")"
winpath() { # MSYS/WSL path → Windows path (identity fallback)
  if command -v cygpath >/dev/null 2>&1; then cygpath -w "$1"
  elif command -v wslpath >/dev/null 2>&1; then wslpath -w "$1"
  else echo "$1"; fi
}
WIN_LOG="$(winpath "$LOG")"
WIN_LAUNCHER="$(winpath "$LAUNCHER")"
q() { # PS single-quoted literal
  local s="$1"; printf "'%s'" "${s//\'/\'\'}"
}

# Params are BAKED INTO the launcher - env vars do not reliably cross the
# UAC elevation boundary (the bare Start-Transcript null-path failure).
{
  printf '$log = %s\n' "$(q "$WIN_LOG")"
  printf '$maxmb = %s\n' $((VHD_MAX * 1024))
  cat <<'PSEOF'
Start-Transcript -Path $log -Force
New-Item -ItemType Directory -Force -Path "C:\devdata" | Out-Null
Set-Content -Path "C:\devdata\attach-devdrive.txt" -Encoding ascii -Value (
  "select vdisk file=`"C:\devdata\devdrive.vhdx`"",
  "attach vdisk",
  "assign letter=V" )
try {
  if (-not (Get-Volume -DriveLetter V -ErrorAction SilentlyContinue)) {
    if (Test-Path "C:\devdata\devdrive.vhdx") {
      diskpart /s "C:\devdata\attach-devdrive.txt"
      if ($LASTEXITCODE -ne 0) { throw "diskpart attach failed ($LASTEXITCODE)" }
    } else {
      Set-Content -Path "C:\devdata\create-devdrive.txt" -Encoding ascii -Value (
        "create vdisk file=`"C:\devdata\devdrive.vhdx`" maximum=$maxmb type=expandable",
        "attach vdisk",
        "create partition primary",
        "assign letter=V" )
      diskpart /s "C:\devdata\create-devdrive.txt"
      if ($LASTEXITCODE -ne 0) { throw "diskpart create/attach failed ($LASTEXITCODE)" }
    }
    format V: /FS:ReFS /Q /DevDrv /Y
    if ($LASTEXITCODE -ne 0) { throw "format /DevDrv failed ($LASTEXITCODE)" }
  }
  "=== devdrv query ==="
  fsutil devdrv query V: 2>&1 | Out-Host
  $q = (fsutil devdrv query V: 2>&1 | Out-String)
  if ($q -match "(?i)untrusted") {
    "volume is untrusted - applying trust"
    fsutil devdrv trust V: 2>&1 | Out-Host
    "trust exit=$LASTEXITCODE"
    if ($LASTEXITCODE -ne 0) { throw "fsutil devdrv trust failed ($LASTEXITCODE)" }
  } elseif ($q -notmatch "(?i)developer volume") {
    throw "V: is not a developer volume - unexpected state; see query above"
  } else {
    "volume already trusted"
  }
  $tr = '"C:\Windows\System32\diskpart.exe" /s "C:\devdata\attach-devdrive.txt"'
  schtasks /Create /TN DevDriveAttach /TR $tr /SC ONLOGON /RL HIGHEST /F | Out-Null
  if ($LASTEXITCODE -ne 0) { throw "scheduled task creation failed ($LASTEXITCODE)" }
  "DEVDRIVE OK"
  schtasks /Query /TN DevDriveAttach | Out-Host
} catch {
  "DEVDRIVE FAILED: $($_.Exception.Message)"
}
Stop-Transcript
PSEOF
} > "$LAUNCHER"

say "Launching elevated setup (approve the UAC prompt)…"
"$PS" -NoProfile -Command "Start-Process -FilePath '$PSHOST' -Verb RunAs -Wait -ArgumentList '-NoProfile','-ExecutionPolicy','Bypass','-File','$WIN_LAUNCHER'" 2>/dev/null || true

if ! grep -q "DEVDRIVE OK" "$LOG" 2>/dev/null; then
  warn "setup did not report success - log tail:"
  tail -n 15 "$LOG" 2>/dev/null || warn "(no log written - UAC declined?)"
  return 1
fi
say "Dev Drive created at V: (ReFS, trusted, auto-attach on logon)."
grep -A3 "Dev Drive" "$LOG" 2>/dev/null | head -n 6 | while IFS= read -r l; do note "$l"; done
if ! "$PS" -NoProfile -Command 'exit [int](-not (Test-Path "V:\"))'; then
  warn "V:\ is not visible - something went wrong."
  return 1
fi

# ── Stage 3: migrate trees + caches (junctions) ───────────────────────────
stage "Migrate trees + caches"
say "Per tree: robocopy /MOVE into the Dev Drive, then junction the"
say "old path back to the new location. Locked trees are left intact"
say "and retried once at the end; anything still busy is listed so you"
say "can close it and re-run this wizard (it only touches leftovers)."

say "Quiescing known dev daemons…"
if command -v gradle >/dev/null 2>&1; then
  gradle --stop >/dev/null 2>&1 || true
  say "  gradle daemons stopped"
fi
"$PS" -NoProfile -Command '
Get-CimInstance Win32_Process |
  Where-Object { $_.CommandLine -and ($_.CommandLine -match "C:\\dev|\\.gradle|\\.bun|\\.m2|pnpm|npm-cache") } |
  ForEach-Object { "PROC`t" + $_.ProcessId + "`t" + $_.Name }
' | tr -d '\r' | while IFS=$'\t' read -r k pid name; do
  [[ "$k" == "PROC" ]] || continue
  note "  in-use: pid $pid $name (close it if you want its tree moved now)"
done

declare -a RETRY_NAME=() RETRY_SRC=() RETRY_DST=()
migrate() { # migrate NAME SRC DST
  local name="$1" src="$2" dst="$3" out rc
  [[ ",$SKIP," == *",$name,"* ]] && { say "  $name: skipped by you"; return 0; }
  [[ ! -e "$src" ]] && { say "  $name: absent, skipped"; return 0; }
  SRC="$src" DST="$dst" "$PS" -NoProfile -Command '
if (Test-Path $env:DST) { "R`t$env:SRC`tdst-exists"; exit }
New-Item -ItemType Directory -Force -Path (Split-Path $env:DST) | Out-Null
$null = robocopy $env:SRC $env:DST /E /MOVE /R:1 /W:1 /NFL /NDL /NP
$rc = $LASTEXITCODE
if ($rc -ge 8) { "R`t$env:SRC`tfail($rc)"; exit }
if (Test-Path $env:SRC) {
  Remove-Item $env:SRC -Recurse -Force -ErrorAction SilentlyContinue
}
if (Test-Path $env:SRC) { "R`t$env:SRC`tin-use-left-intact"; exit }
New-Item -ItemType Junction -Path $env:SRC -Target $env:DST | Out-Null
$gb = [math]::Round((Get-ChildItem $env:DST -Recurse -File -ErrorAction SilentlyContinue |
  Measure-Object Length -Sum).Sum/1GB, 1)
"R`t$env:SRC`tok`t$gb"
' | { IFS=$'\t' read -r tag spath status gb || true
    case "$status" in
      ok)             say "  $name → $dst  (${gb:-?} GB)  ✓ junctioned";;
      in-use*)        warn "  $name: files in use - left at $src, retrying soon"
                      RETRY_NAME+=("$name"); RETRY_SRC+=("$src"); RETRY_DST+=("$dst");;
      dst-exists)     warn "  $name: target already exists at $dst - skipped";;
      fail*)          warn "  $name: robocopy failed ($status) - source intact";;
      *)              warn "  $name: unexpected result - check $src";;
    esac; }
}
say "Migrating C:\dev children (busy ones skip cleanly)…"
if [[ ",$SKIP," == *",dev,"* ]]; then
  say "  C:\dev: skipped by you"
else
  while IFS=$'\t' read -r n p; do
    [[ -n "$n" ]] || continue
    migrate "$n" "$p" "V:\\dev\\$n"
  done < <("$PS" -NoProfile -Command 'Get-ChildItem "C:\dev" -Directory | ForEach-Object { $_.Name + "`t" + $_.FullName }' | tr -d '\r')
fi
say "Migrating caches…"
migrate gradle   "$USERPROFILE/.gradle"            "V:\\caches\\.gradle"
migrate bun      "$USERPROFILE/.bun"               "V:\\caches\\.bun"
migrate m2       "$USERPROFILE/.m2"                "V:\\caches\\.m2"
migrate pnpm     "$LOCALAPPDATA/pnpm"              "V:\\caches\\pnpm"
migrate npmcache "$LOCALAPPDATA/npm-cache"         "V:\\caches\\npm-cache"

# One retry pass over trees that were busy (transient locks often clear).
if (( ${#RETRY_NAME[@]} > 0 )); then
  say "Retrying busy trees once…"
  RN=("${RETRY_NAME[@]}"); RS=("${RETRY_SRC[@]}"); RD=("${RETRY_DST[@]}")
  RETRY_NAME=(); RETRY_SRC=(); RETRY_DST=()
  for i in "${!RN[@]}"; do migrate "${RN[$i]}" "${RS[$i]}" "${RD[$i]}"; done
fi
if (( ${#RETRY_NAME[@]} > 0 )); then
  warn "Still busy after retry - close the apps above (or reboot), then"
  warn "re-run this wizard: it skips everything already moved and only"
  warn "finishes the leftovers:"
  for i in "${!RETRY_NAME[@]}"; do note "  ${RETRY_NAME[$i]} at ${RETRY_SRC[$i]}"; done
else
  say "All trees migrated."
fi

# ── Stage 4: verify + wrap-up ─────────────────────────────────────────────
stage "Verify + wrap-up"
"$PS" -NoProfile -Command '
$b = New-Object byte[] (200MB)
foreach ($f in @("V:\speedtest.bin", (Join-Path $env:TEMP "speedtest-c.bin"))) {
  $t = Measure-Command { [IO.File]::WriteAllBytes($f, $b) }
  "SPEED`t$f`t" + [math]::Round(200 / $t.TotalSeconds, 0) + " MB/s"
  Remove-Item $f -Force -ErrorAction SilentlyContinue
}
"CFREE`t" + [math]::Round((Get-Volume C).SizeRemaining/1GB,1)
' | tr -d '\r' | while IFS=$'\t' read -r k a b; do
  case "$k" in
    SPEED) say "  write speed $a: $b";;
    CFREE) say "C: free now: $a GB";;
  esac
done
note ""
note "Survives reboots: scheduled task 'DevDriveAttach' re-attaches the"
note "VHD at every logon (created in Stage 2)."
note ""
note "Rollback (all reversible):"
note "  - a tree: Remove-Item <junction>; move the folder back from V:"
note "  - the drive (elevated): schtasks /Delete /TN DevDriveAttach /F,"
note "    diskpart 'select vdisk file=C:\devdata\devdrive.vhdx' + 'detach"
note "    vdisk', then delete C:\devdata"

finish
}

run_wizard "$@"; exit
